?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Background Remover</title><meta name="description" content="Remove image backgrounds quickly in your browser with SmartToolz."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,500,0,0&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--p2:#8b7cff;--ink:#171923;--muted:#7a8191;--line:#e6e8ee;--bg:#f7f8fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.material-symbols-rounded{font-size:20px;line-height:1}.tool-page{width:min(760px,calc(100% - 24px));margin:0 auto;padding:18px 0 26px}.tool-page .tool-seo-intro{display:none!important}.intro{text-align:center;margin:0 0 12px}.intro h1{margin:0;font-size:clamp(26px,4vw,36px);letter-spacing:-1.5px}.intro h1 span{color:var(--p)}.intro p{margin:6px 0 0;color:var(--muted);font-size:9px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 10px 30px rgba(23,26,36,.05)}.bar{height:44px;padding:0 12px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.state{display:flex;align-items:center;gap:8px;font-size:8px;font-weight:800}.state i{width:7px;height:7px;border-radius:50%;background:#22c55e;box-shadow:0 0 0 4px #dcfce7}.bar button{border:1px solid var(--line);background:#fff;border-radius:8px;padding:7px 9px;font-size:8px;font-weight:800;color:#555d6d;cursor:pointer}.area{padding:10px}.drop,.viewer{position:relative;border:1px solid var(--line);border-radius:13px;overflow:hidden}.drop{min-height:255px;display:grid;place-items:center;text-align:center;padding:18px;background:#fafbfe}.drop.drag{border-color:var(--p);background:#f7f6ff}.upload{width:50px;height:50px;margin:auto;border-radius:14px;display:grid;place-items:center;background:#eeecff;color:var(--p)}.drop h2{margin:9px 0 5px;font-size:18px;letter-spacing:-.35px}.drop p{margin:0 auto 13px;max-width:350px;color:var(--muted);font-size:9px;line-height:1.55}.choose{display:inline-flex;align-items:center;gap:7px;padding:10px 16px;border-radius:10px;background:var(--p);color:#fff;font-size:9px;font-weight:800;cursor:pointer}.meta{margin-top:8px;color:#a0a6b2;font-size:7px}.viewer{display:none;min-height:220px;padding:12px;align-items:center;justify-content:center;background:repeating-conic-gradient(#eef1f5 0 25%,#fafbfc 0 50%) 50%/18px 18px}.viewer canvas{display:block;max-width:100%;max-height:300px;border-radius:10px;box-shadow:0 10px 24px rgba(18,22,34,.12)}.magic{position:absolute;inset:0;display:none;pointer-events:none;align-items:center;justify-content:center;background:radial-gradient(circle at center,rgba(99,91,255,.08),transparent 52%)}.processing .magic{display:flex}.magic-line{position:absolute;left:7%;right:7%;height:2px;background:linear-gradient(90deg,transparent,#756dff 20%,#fff 50%,#756dff 80%,transparent);box-shadow:0 0 18px rgba(99,91,255,.7);animation:magic 1.7s ease-in-out infinite}.magic-ring{width:92px;height:92px;border:1px solid rgba(99,91,255,.3);border-radius:50%;box-shadow:0 0 24px rgba(99,91,255,.18);animation:ring 1.7s ease-in-out infinite}@keyframes magic{0%{top:10%;opacity:0}18%{opacity:1}50%{top:50%;opacity:1}82%{opacity:1}100%{top:90%;opacity:0}}@keyframes ring{0%,100%{transform:scale(.78);opacity:.3}50%{transform:scale(1.08);opacity:.9}}.progress{position:absolute;left:12px;right:12px;bottom:12px;padding:9px 11px;border-radius:10px;background:rgba(20,23,31,.92);color:#fff;backdrop-filter:blur(8px)}.prow{display:flex;justify-content:space-between;font-size:7px;font-weight:800}.track{height:4px;margin-top:6px;border-radius:99px;background:#323642;overflow:hidden}.track i{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--p),#9b92ff);transition:width .18s ease}.actions{display:none;gap:7px;padding-top:9px}.actions button{flex:1;border:1px solid var(--line);background:#fff;border-radius:9px;padding:10px;font-size:8px;font-weight:800;cursor:pointer;color:#555d6d}.actions .primary{background:#171923;border-color:#171923;color:#fff}.result{display:none;margin-top:9px}.result-title{font-size:9px;font-weight:800;margin:0 0 7px}.result-box{display:flex;align-items:center;justify-content:center;min-height:170px;padding:12px;border:1px solid var(--line);border-radius:13px;background:repeating-conic-gradient(#eef1f5 0 25%,#fafbfc 0 50%) 50%/18px 18px}.result-box canvas{display:block;max-width:100%;max-height:300px;border-radius:10px;box-shadow:0 8px 22px rgba(18,22,34,.1)}@media(max-width:600px){.tool-page{width:calc(100% - 14px);padding-top:12px}.intro h1{font-size:26px}.drop{min-height:230px}.viewer{min-height:190px}.viewer canvas,.result-box canvas{max-height:270px}.actions{flex-direction:column}}</style></head><body><?php require_once __DIR__.'/../header.php'; ?><main class="tool-page"><div class="intro"><h1>Background <span>Remover</span></h1><p>Remove the background from any image in your browser.</p></div><section class="card"><div class="bar"><div class="state"><i></i><span id="status">Ready</span></div><button id="new" type="button">New image</button></div><div class="area"><div class="drop" id="drop"><div><div class="upload"><span class="material-symbols-rounded">content_cut</span></div><h2>Drop an image here</h2><p>Choose a photo and SmartToolz will remove the background automatically.</p><label class="choose"><span class="material-symbols-rounded">upload_file</span> Choose image<input id="picker" hidden type="file" accept="image/png,image/jpeg,image/webp"></label><div class="meta">PNG • JPG • WebP</div></div></div><div class="viewer" id="viewer"><canvas id="preview"></canvas><div class="magic"><div class="magic-ring"></div><div class="magic-line"></div></div><div class="progress" id="progress"><div class="prow"><span>Removing background…</span><span id="pct">0%</span></div><div class="track"><i id="fill"></i></div></div></div><div class="actions" id="actions"><button id="again" type="button">Try another</button><button id="download" class="primary" type="button">Download PNG</button></div><div class="result" id="result"><div class="result-title">Result</div><div class="result-box"><canvas id="resultCanvas"></canvas></div></div></div></section></main><script type="module">import{removeBackground}from'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';const $=id=>document.getElementById(id),picker=$('picker'),drop=$('drop'),viewer=$('viewer'),preview=$('preview'),result=$('result'),resultCanvas=$('resultCanvas'),status=$('status'),actions=$('actions'),progress=$('progress'),fill=$('fill'),pct=$('pct');let outUrl='',sourceUrl='';function reset(){picker.value='';drop.style.display='grid';viewer.style.display='none';viewer.classList.remove('processing');progress.style.display='block';actions.style.display='none';result.style.display='none';status.textContent='Ready';if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl);outUrl='';sourceUrl=''}function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src})}function alphaCrop(img){const c=document.createElement('canvas'),x=c.getContext('2d',{willReadFrequently:true});c.width=img.naturalWidth;c.height=img.naturalHeight;x.drawImage(img,0,0,c.width,c.height);const d=x.getImageData(0,0,c.width,c.height).data;let l=c.width,t=c.height,r=-1,b=-1;for(let y=0;y<c.height;y++){for(let xx=0;xx<c.width;xx++){if(d[(y*c.width+xx)*4+3]>12){l=Math.min(l,xx);r=Math.max(r,xx);t=Math.min(t,y);b=Math.max(b,y)}}}if(r<0)return c;const pad=Math.max(8,Math.round(Math.min(c.width,c.height)*.02));l=Math.max(0,l-pad);t=Math.max(0,t-pad);r=Math.min(c.width-1,r+pad);b=Math.min(c.height-1,b+pad);const w=r-l+1,h=b-t+1,o=document.createElement('canvas');o.width=w;o.height=h;o.getContext('2d').drawImage(c,l,t,w,h,0,0,w,h);return o}function paintFit(target,source,maxW,maxH){const s=Math.min(maxW/source.width,maxH/source.height,1),w=Math.max(1,Math.round(source.width*s)),h=Math.max(1,Math.round(source.height*s)),ctx=target.getContext('2d');target.width=w;target.height=h;ctx.clearRect(0,0,w,h);ctx.drawImage(source,0,0,w,h)}async function process(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type))return;drop.style.display='none';viewer.style.display='flex';viewer.classList.add('processing');actions.style.display='none';result.style.display='none';progress.style.display='block';fill.style.width='4%';pct.textContent='4%';status.textContent='Removing background';sourceUrl=URL.createObjectURL(file);try{const source=await loadImage(sourceUrl);paintFit(preview,source,600,280);const blob=await removeBackground(file,{model:'small',output:{format:'image/png',quality:1},progress:(name,current,total)=>{const p=total?Math.max(5,Math.min(96,Math.round(current/total*91)+5)):8;fill.style.width=p+'%';pct.textContent=p+'%'}});const rawUrl=URL.createObjectURL(blob);try{const raw=await loadImage(rawUrl),cropped=alphaCrop(raw);paintFit(resultCanvas,cropped,600,300);paintFit(preview,cropped,600,280);const croppedBlob=await new Promise(resolve=>cropped.toBlob(resolve,'image/png',1));outUrl=URL.createObjectURL(croppedBlob||blob)}finally{URL.revokeObjectURL(rawUrl)}fill.style.width='100%';pct.textContent='100%';setTimeout(()=>{progress.style.display='none';viewer.classList.remove('processing');actions.style.display='flex';result.style.display='block';status.textContent='Done'},180)}catch(err){console.error(err);reset();status.textContent='Could not process image'}}picker.onchange=()=>{const f=picker.files?.[0];picker.value='';process(f)};drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');process(e.dataTransfer.files?.[0])});$('new').onclick=reset;$('again').onclick=reset;$('download').onclick=()=>{if(!outUrl)return;const a=document.createElement('a');a.href=outUrl;a.download='smarttoolz-background-removed.png';document.body.appendChild(a);a.click();a.remove()};window.addEventListener('beforeunload',()=>{if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl)});</script></body></html>